/* Smoke: Create Web App wizard "Secure unique default hostname on." (properties.autoGeneratedDomainNameLabelScope).
 * Drives the REAL wizard, then checks the hostname is consistent in ARM (defaultHostName / hostNames), the app blade, and
 * a classic (switch off) app keeps <name>.azurewebsites.net.
 *   BASE=http://127.0.0.1:9142 PW=<playwright path> [SHOT=<dir>] node consoles/tests/smoke-azure-apphost.mjs */
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const pw = require(process.env.PW || "playwright");
const BASE = process.env.BASE || "http://127.0.0.1:9142";
const UI = `${BASE}${process.env.UI_PATH || "/v4/azure/"}`;
const WIRE = `${BASE}${process.env.WIRE_PATH || "/_wire"}`;
const SUB = "00000000-0000-0000-0000-cloudlearn01";
const n = Date.now() % 100000, RG = `apphost-rg-${n}`, UNIQ = `uniq${n}`, CLASSIC = `classic${n}`;
let pass = 0, fail = 0;
const ok = (name, c, d = "") => { c ? pass++ : fail++; console.log(`[${c ? "PASS" : "FAIL"}] ${name}${c ? "" : " " + d}`); };
let pg;
const arm = (m, path, body, v = "2023-12-01") => pg.evaluate(async ([m, url, body]) => {
  const r = await fetch(url, { method: m, headers: { "content-type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
  const t = await r.text(); return { status: r.status, body: t ? JSON.parse(t) : null };
}, [m, `${WIRE}/subscriptions/${SUB}${path}${path.includes("?") ? "&" : "?"}api-version=${v}`, body]);
const b = await pw.chromium.launch(); pg = await (await b.newContext({ viewport: { width: 1400, height: 1000 } })).newPage();
await pg.goto(UI, { waitUntil: process.env.NANO ? "domcontentloaded" : "networkidle" });
if (process.env.NANO) await pg.waitForFunction(() => navigator.serviceWorker?.controller && window.__vyomiNanoReady, null, { timeout: 240000, polling: 500 });
await arm("PUT", `/resourcegroups/${RG}`, { location: "eastus" }, "2021-04-01");
const shot = async (name) => { if (process.env.SHOT) await pg.screenshot({ path: `${process.env.SHOT}/${name}.png`, fullPage: true }); };

async function wizard(app, secure, scope) {
  await pg.goto(`${UI}#/appservices/create`); await pg.waitForTimeout(1500);
  await pg.getByLabel("Resource Group", { exact: true }).selectOption(RG);
  await pg.getByLabel("Name", { exact: true }).fill(app);
  if (secure) {
    await pg.getByLabel("Secure unique default hostname on.").check();
    await pg.getByLabel("Domain name label scope").selectOption(scope);
    const help = await pg.getByTestId("host-help").innerText();
    ok("help text shows the pattern and is honest about the hash", help.includes(`${app}-<hash>.eastus-01.azurewebsites.net`) && /not identical/i.test(help), help);
    await shot("host-basics");
  }
  await pg.getByRole("button", { name: /Review \+ create/ }).first().click(); await pg.waitForTimeout(500);
  await shot(secure ? "host-review" : "classic-review");
  await pg.getByRole("button", { name: "Create", exact: true }).click();
  await pg.waitForURL(new RegExp(`#/appservices/${RG}/${app}`), { timeout: 30000 }); await pg.waitForTimeout(1500);
}

await wizard(UNIQ, true, "SubscriptionReuse");
const site = (await arm("GET", `/resourceGroups/${RG}/providers/Microsoft.Web/sites/${UNIQ}`)).body;
const p = site.properties, host = p.defaultHostName;
ok("ARM: scope persisted", p.autoGeneratedDomainNameLabelScope === "SubscriptionReuse", JSON.stringify(p).slice(0, 300));
ok("ARM: defaultHostName = <name>-<hash>.<region>-01.azurewebsites.net", new RegExp(`^${UNIQ}-[0-9a-f]{10}\\.eastus-01\\.azurewebsites\\.net$`).test(host), host);
ok("ARM: hostNames contains the default host", (p.hostNames || []).includes(host), JSON.stringify(p.hostNames));
const text = await pg.locator("body").innerText();
ok("UI overview shows the same default domain", text.includes(host), text.slice(0, 400));
ok("UI Browse link points at the same host", (await pg.locator(`a[href="https://${host}"]`).count()) > 0);
await shot("host-overview");
const pub = (await arm("POST", `/resourceGroups/${RG}/providers/Microsoft.Web/sites/${UNIQ}/publishxml`)).body?.value || "";
ok("publish profile uses the same host (+ scm host)", pub.includes(`destinationAppUrl="https://${host}"`) && pub.includes(`${host.split(".")[0]}.scm.`), pub);

await wizard(CLASSIC, false);
const c = (await arm("GET", `/resourceGroups/${RG}/providers/Microsoft.Web/sites/${CLASSIC}`)).body.properties;
ok("switch off: classic <name>.azurewebsites.net and no scope", c.defaultHostName === `${CLASSIC}.azurewebsites.net` && !c.autoGeneratedDomainNameLabelScope, JSON.stringify(c).slice(0, 200));
ok("list page route has no not-simulated hostname gap", !(await (async () => { await pg.goto(`${UI}#/appservices`); await pg.waitForTimeout(1200); return pg.locator("[data-vyomi-not-simulated]").filter({ hasText: "name-collision" }).count(); })()));
await b.close();
console.log(`\n${pass} passed, ${fail} failed`); process.exit(fail ? 1 : 0);
